#!/bin/bash\n\necho "🚀 Starting Full-Stack Application Setup..."\necho ""\n\n# Colors\nGREEN='\\033[0;32m'\nBLUE='\\033[0;34m'\nYELLOW='\\033[1;33m'\nNC='\\033[0m' # No Color\n\n# Check if Node.js is installed\nif ! command -v node &> /dev/null; then\n    echo "❌ Node.js is not installed. Please install Node.js first."\n    exit 1\nfi\n\necho -e "${BLUE}✓ Node.js found: $(node --version)${NC}"\necho -e "${BLUE}✓ npm found: $(npm --version)${NC}"\necho ""\n\n# Install root dependencies\necho -e "${YELLOW}📦 Installing root dependencies...${NC}"\nnpm install\n\n# Install server dependencies\necho -e "${YELLOW}📦 Installing server dependencies...${NC}"\ncd server\nnpm install\ncd ..\n\n# Install client dependencies\necho -e "${YELLOW}📦 Installing client dependencies...${NC}"\ncd client\nnpm install\ncd ..\n\necho ""\necho -e "${GREEN}✅ Setup completed successfully!${NC}"\necho ""\necho -e "${BLUE}Next steps:${NC}"\necho -e "1. Setup your database (PostgreSQL must be running)"\necho -e "   ${YELLOW}npm run setup-db${NC}"\necho ""\necho -e "2. Copy .env files and configure:"\necho -e "   ${YELLOW}cp server/.env.example server/.env${NC}"\necho -e "   ${YELLOW}cp client/.env.example client/.env.local${NC}"\necho ""\necho -e "3. Run development servers:"\necho -e "   ${YELLOW}npm run dev${NC}"\necho ""\necho -e "4. Open browser and navigate to:"\necho -e "   ${YELLOW}http://localhost:3000${NC}"\necho ""\necho -e "${GREEN}Happy coding! 🎉${NC}"\n